from __future__ import annotations

__all__ = ["flatten_"]

def flatten_(nested_list: list[int | list]) -> list[int]:
    """Flatten a nested list of integers of arbitrary depth.

    Args:
        nested_list: A nested list of integers.

    Returns:
        A flattened list of integers.

    Examples:
        >>> flatten_([1, [2, [3, 4], 5], 6])
        [1, 2, 3, 4, 5, 6]
    """
    def _flatten(lst):
        for item in lst:
            if isinstance(item, list):
                yield from _flatten(item)
            else:
                yield item

    if not nested_list:
        raise ValueError("nested_list must not be empty")

    return list(_flatten(nested_list))
